package com.snaphere.api.auth;
import com.snaphere.api.common.error.*; import com.snaphere.api.common.web.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; JwtAuthenticationFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException { try { String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){ AuthPrincipal p=jwt.verify(h.substring(7)); User u=users.findById(p.userId()).orElseThrow(()->new ApiException(ErrorCode.AUTH_REQUIRED)); if(u.getStatus()==UserStatus.WITHDRAWN)throw new ApiException(ErrorCode.AUTH_REQUIRED); if(!u.isOnboardingCompleted() && requiresTerms(r)) throw new ApiException(ErrorCode.AUTH_TERMS_REQUIRED); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,List.of(new SimpleGrantedAuthority("ROLE_"+p.role().name())))); } c.doFilter(r,s); } catch(ApiException e){s.setStatus(e.errorCode().status().value());s.setContentType(MediaType.APPLICATION_JSON_VALUE);new com.fasterxml.jackson.databind.ObjectMapper().writeValue(s.getOutputStream(),ApiResponse.fail(ErrorBody.of(e.errorCode()),TraceIdFilter.currentTraceId(r)));} finally {SecurityContextHolder.clearContext();} } private boolean requiresTerms(HttpServletRequest r){String p=r.getRequestURI();return "POST".equals(r.getMethod())&&!p.endsWith("/auth/onboarding")&&!p.endsWith("/auth/logout")&&!p.endsWith("/auth/logout-all");} }
